create extension if not exists pgcrypto;
create type public.portal_role as enum ('reader','author','admin');
create type public.book_status as enum ('draft','writing','finished','archived');
create type public.payment_status as enum ('pending','confirmed','rejected','paid');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,role public.portal_role not null default 'reader',is_active boolean not null default false,pin_hash text not null,is_primary_admin boolean not null default false,created_at timestamptz not null default now());
create table public.author_private_data(author_id uuid primary key references public.profiles(id) on delete cascade,legal_name text not null,birth_date date,country text,state text,city text,address text,postal_code text,phone text,tax_data text,created_at timestamptz not null default now());
create table public.author_pseudonyms(id bigint generated always as identity primary key,author_id uuid not null references public.profiles(id) on delete cascade,pseudonym text not null,is_active boolean not null default true,created_at timestamptz not null default now(),unique(author_id,pseudonym));
create table public.books(id bigint generated always as identity primary key,author_id uuid not null references public.profiles(id) on delete cascade,pseudonym_id bigint references public.author_pseudonyms(id),title text not null,pseudonym text not null,description text,status public.book_status not null default 'draft',started_on date default current_date,finished_on date,pdf_price_mxn numeric(10,2) not null default 500,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.chapters(id bigint generated always as identity primary key,book_id bigint not null references public.books(id) on delete cascade,title text not null,chapter_order int not null,unique(book_id,chapter_order));
create table public.pages(id bigint generated always as identity primary key,book_id bigint not null references public.books(id) on delete cascade,chapter_id bigint references public.chapters(id) on delete cascade,page_order int not null,content text not null default '',written_on date not null default current_date,published_at timestamptz,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(book_id,page_order));
create table public.reader_periods(id bigint generated always as identity primary key,reader_id uuid not null references public.profiles(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,payment_amount_mxn numeric(10,2) not null default 100,payment_status public.payment_status not null default 'pending',created_at timestamptz not null default now());
create table public.reader_book_selections(id bigint generated always as identity primary key,period_id bigint not null references public.reader_periods(id) on delete cascade,reader_id uuid not null references public.profiles(id) on delete cascade,book_id bigint not null references public.books(id) on delete cascade,selected_at timestamptz not null default now(),unique(period_id,book_id));
create table public.reader_progress(reader_id uuid not null references public.profiles(id) on delete cascade,book_id bigint not null references public.books(id) on delete cascade,last_page_order int not null default 0,updated_at timestamptz not null default now(),primary key(reader_id,book_id));
create table public.author_earnings(id bigint generated always as identity primary key,author_id uuid not null references public.profiles(id) on delete cascade,reader_id uuid not null references public.profiles(id) on delete cascade,period_id bigint not null references public.reader_periods(id) on delete cascade,book_id bigint not null references public.books(id) on delete cascade,amount_mxn numeric(10,2) not null,accrued_at timestamptz not null default now());
create table public.author_payouts(id bigint generated always as identity primary key,author_id uuid not null references public.profiles(id) on delete cascade,period_start date not null,period_end date not null,amount_mxn numeric(10,2) not null,status public.payment_status not null default 'pending',paid_at timestamptz,created_at timestamptz not null default now());
create or replace function public.enforce_admin_limit() returns trigger language plpgsql as $$ begin if new.role='admin' and (tg_op='INSERT' or old.role is distinct from 'admin') then if (select count(*) from public.profiles where role='admin')>=5 then raise exception 'Máximo 5 administradores'; end if; end if; return new; end $$;
create trigger trg_admin_limit before insert or update of role on public.profiles for each row execute function public.enforce_admin_limit();
create or replace function public.verify_portal_pin(p_pin text) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and pin_hash=crypt(p_pin,pin_hash)); $$;
revoke all on function public.verify_portal_pin(text) from public; grant execute on function public.verify_portal_pin(text) to authenticated;
create or replace function public.enforce_three_books() returns trigger language plpgsql as $$ begin if (select count(*) from public.reader_book_selections where period_id=new.period_id)>=3 then raise exception 'Solo 3 obras por periodo'; end if; return new; end $$;
create trigger trg_three_books before insert on public.reader_book_selections for each row execute function public.enforce_three_books();
create or replace function public.lock_reader_selection() returns trigger language plpgsql as $$ declare v_end timestamptz; begin select ends_at into v_end from public.reader_periods where id=old.period_id; if v_end>now() then raise exception 'Selección fija hasta terminar los 30 días'; end if; if tg_op='DELETE' then return old; else return new; end if; end $$;
create trigger trg_lock_selection before update or delete on public.reader_book_selections for each row execute function public.lock_reader_selection();
create or replace function public.prevent_reader_backtracking() returns trigger language plpgsql as $$ begin if new.last_page_order<old.last_page_order then raise exception 'No se puede regresar a páginas leídas'; end if; return new; end $$;
create trigger trg_no_backtracking before update on public.reader_progress for each row execute function public.prevent_reader_backtracking();
create or replace function public.calculate_period_author_earnings(p_period_id bigint) returns void language plpgsql security definer set search_path=public as $$ declare v_reader uuid;v_count int;v_total numeric(10,2);r record;v_each numeric(10,2);v_remaining numeric(10,2);v_i int:=0; begin select reader_id,round(payment_amount_mxn*0.20,2) into v_reader,v_total from reader_periods where id=p_period_id and payment_status='confirmed'; if v_reader is null then raise exception 'Periodo no confirmado'; end if; select count(*) into v_count from reader_book_selections where period_id=p_period_id; if v_count<1 then return; end if; delete from author_earnings where period_id=p_period_id; v_each:=trunc((v_total/v_count)::numeric,2);v_remaining:=v_total; for r in select s.book_id,b.author_id from reader_book_selections s join books b on b.id=s.book_id where s.period_id=p_period_id order by s.id loop v_i:=v_i+1; if v_i=v_count then insert into author_earnings(author_id,reader_id,period_id,book_id,amount_mxn) values(r.author_id,v_reader,p_period_id,r.book_id,v_remaining); else insert into author_earnings(author_id,reader_id,period_id,book_id,amount_mxn) values(r.author_id,v_reader,p_period_id,r.book_id,v_each);v_remaining:=v_remaining-v_each; end if; end loop; end $$;
